            }
            return array(
                'jsonrpc' => '2.0',
                'id' => $requestId,
                'method' => 'public/auth',
                'params' => $params,
            );
        }
        // the gateway closes a socket after ~30s without client messages; protocol-level pings do not count
        return array(
            'jsonrpc' => '2.0',
